import { PostHogService } from "./posthogService";

export class WebVitalsService {
  private static isInitialized = false;
  private static userContext: { username?: string; organization?: string; user_id?: string } = {};

  /**
   * Initialize web vitals tracking with user context
   */
  static initialize(userContext?: { username?: string; organization?: string; user_id?: string }) {
    if (WebVitalsService.isInitialized) return;

    WebVitalsService.userContext = userContext || {};

    // Track Core Web Vitals
    WebVitalsService.trackCoreWebVitals();

    // Track page lifecycle events
    WebVitalsService.trackPageLifecycle();

    // Track page visibility changes
    WebVitalsService.trackVisibilityChanges();

    // Track user engagement
    WebVitalsService.trackUserEngagement();

    WebVitalsService.isInitialized = true;
  }

  /**
   * Track Core Web Vitals (CLS, FID, LCP)
   */
  private static trackCoreWebVitals() {
    // Use the web-vitals library if available, otherwise implement basic tracking
    if (typeof window === "undefined") return;

    // Cumulative Layout Shift (CLS)
    WebVitalsService.observeLayoutShift();

    // Largest Contentful Paint (LCP)
    WebVitalsService.observeLargestContentfulPaint();

    // First Input Delay (FID) - will be replaced by INP
    WebVitalsService.observeFirstInputDelay();

    // Interaction to Next Paint (INP) - new metric replacing FID
    WebVitalsService.observeInteractionToNextPaint();

    // Time to First Byte (TTFB)
    WebVitalsService.observeTimeToFirstByte();
  }

  private static observeLayoutShift() {
    if (!("PerformanceObserver" in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        let cumulativeScore = 0;

        for (const entry of list.getEntries()) {
          if (!(entry as any).hadRecentInput) {
            cumulativeScore += (entry as any).value;
          }
        }

        if (cumulativeScore > 0) {
          WebVitalsService.sendWebVitalEvent(
            "CLS",
            cumulativeScore,
            WebVitalsService.rateWebVital("CLS", cumulativeScore),
          );
        }
      });

      observer.observe({ type: "layout-shift", buffered: true });
    } catch (_error) {
      // Could not observe layout shift
    }
  }

  private static observeLargestContentfulPaint() {
    if (!("PerformanceObserver" in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        const entries = list.getEntries();
        const lastEntry = entries[entries.length - 1];
        const value = lastEntry.startTime;

        WebVitalsService.sendWebVitalEvent(
          "LCP",
          value,
          WebVitalsService.rateWebVital("LCP", value),
        );
      });

      observer.observe({ type: "largest-contentful-paint", buffered: true });
    } catch (_error) {
      // Could not observe LCP
    }
  }

  private static observeFirstInputDelay() {
    if (!("PerformanceObserver" in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          const value = (entry as any).processingStart - entry.startTime;
          WebVitalsService.sendWebVitalEvent(
            "FID",
            value,
            WebVitalsService.rateWebVital("FID", value),
          );
        }
      });

      observer.observe({ type: "first-input", buffered: true });
    } catch (_error) {
      // Could not observe FID
    }
  }

  private static observeInteractionToNextPaint() {
    if (!("PerformanceObserver" in window)) return;

    try {
      const observer = new PerformanceObserver((list) => {
        for (const entry of list.getEntries()) {
          const value = (entry as any).duration;
          WebVitalsService.sendWebVitalEvent(
            "INP",
            value,
            WebVitalsService.rateWebVital("INP", value),
          );
        }
      });

      observer.observe({ type: "interaction", buffered: true });
    } catch (_error) {
      // Could not observe INP
    }
  }

  private static observeTimeToFirstByte() {
    if (!("performance" in window) || !("timing" in performance)) return;

    try {
      window.addEventListener("load", () => {
        const navigation = performance.getEntriesByType(
          "navigation",
        )[0] as PerformanceNavigationTiming;
        if (navigation) {
          const ttfb = navigation.responseStart - navigation.requestStart;
          WebVitalsService.sendWebVitalEvent(
            "TTFB",
            ttfb,
            WebVitalsService.rateWebVital("TTFB", ttfb),
          );
        }
      });
    } catch (_error) {
      // Could not observe TTFB
    }
  }

  /**
   * Track page lifecycle events
   */
  private static trackPageLifecycle() {
    if (typeof window === "undefined") return;

    // Page load
    window.addEventListener("load", () => {
      WebVitalsService.sendLifecycleEvent("page_loaded", {
        load_time: performance.now(),
        referrer: document.referrer,
        url: window.location.href,
      });
    });

    // Page unload/beforeunload
    window.addEventListener("beforeunload", () => {
      WebVitalsService.sendLifecycleEvent("page_beforeunload", {
        session_duration: performance.now(),
        url: window.location.href,
      });
    });

    // Page leave (using pagehide for better mobile support)
    window.addEventListener("pagehide", (event) => {
      WebVitalsService.sendLifecycleEvent("page_leave", {
        session_duration: performance.now(),
        url: window.location.href,
        persisted: event.persisted,
      });
    });

    // Back/forward cache
    window.addEventListener("pageshow", (event) => {
      WebVitalsService.sendLifecycleEvent("page_show", {
        from_cache: event.persisted,
        url: window.location.href,
      });
    });
  }

  /**
   * Track visibility changes
   */
  private static trackVisibilityChanges() {
    if (typeof document === "undefined") return;

    document.addEventListener("visibilitychange", () => {
      WebVitalsService.sendLifecycleEvent("visibility_change", {
        visibility_state: document.visibilityState,
        hidden: document.hidden,
        url: window.location.href,
      });
    });
  }

  /**
   * Track user engagement metrics
   */
  private static trackUserEngagement() {
    if (typeof window === "undefined") return;

    let scrollDepth = 0;
    let maxScrollDepth = 0;

    // Scroll tracking
    window.addEventListener("scroll", () => {
      const scrollTop = window.pageYOffset || document.documentElement.scrollTop;
      const windowHeight = window.innerHeight;
      const documentHeight = document.documentElement.scrollHeight;

      scrollDepth = Math.round(((scrollTop + windowHeight) / documentHeight) * 100);

      if (scrollDepth > maxScrollDepth) {
        maxScrollDepth = scrollDepth;

        // Track milestone scroll depths
        if (maxScrollDepth >= 25 && maxScrollDepth < 50) {
          WebVitalsService.sendEngagementEvent("scroll_25_percent");
        } else if (maxScrollDepth >= 50 && maxScrollDepth < 75) {
          WebVitalsService.sendEngagementEvent("scroll_50_percent");
        } else if (maxScrollDepth >= 75 && maxScrollDepth < 100) {
          WebVitalsService.sendEngagementEvent("scroll_75_percent");
        } else if (maxScrollDepth >= 100) {
          WebVitalsService.sendEngagementEvent("scroll_100_percent");
        }
      }
    });

    // Click tracking
    document.addEventListener("click", (event) => {
      const target = event.target as HTMLElement;
      WebVitalsService.sendEngagementEvent("user_click", {
        element_type: target.tagName.toLowerCase(),
        element_class: target.className,
        element_id: target.id,
        url: window.location.href,
      });
    });
  }

  /**
   * Rate web vital based on Google's thresholds
   */
  private static rateWebVital(
    metric: string,
    value: number,
  ): "good" | "needs-improvement" | "poor" {
    const thresholds = {
      CLS: { good: 0.1, needsImprovement: 0.25 },
      LCP: { good: 2500, needsImprovement: 4000 },
      FID: { good: 100, needsImprovement: 300 },
      INP: { good: 200, needsImprovement: 500 },
      TTFB: { good: 800, needsImprovement: 1800 },
    };

    const threshold = thresholds[metric as keyof typeof thresholds];
    if (!threshold) return "good";

    if (value <= threshold.good) return "good";
    if (value <= threshold.needsImprovement) return "needs-improvement";
    return "poor";
  }

  /**
   * Send web vital event to PostHog
   */
  private static sendWebVitalEvent(metric: string, value: number, rating: string) {
    PostHogService.captureEvent("web_vital_measured", {
      metric_name: metric,
      metric_value: value,
      metric_rating: rating,
      url: window.location.href,
      user_agent: navigator.userAgent,
      ...WebVitalsService.userContext,
    });
  }

  /**
   * Send lifecycle event to PostHog
   */
  private static sendLifecycleEvent(event: string, properties: Record<string, any> = {}) {
    PostHogService.captureEvent(event, {
      ...properties,
      timestamp: Date.now(),
      user_agent: navigator.userAgent,
      ...WebVitalsService.userContext,
    });
  }

  /**
   * Send engagement event to PostHog
   */
  private static sendEngagementEvent(event: string, properties: Record<string, any> = {}) {
    PostHogService.captureEvent(event, {
      ...properties,
      timestamp: Date.now(),
      ...WebVitalsService.userContext,
    });
  }
}
